export function parseClaimTimeoutInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedClaimTimeoutInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 13) {
    // TODO: Coded error.
    throw new Error("Not enough accounts");
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      lot: getNextAccount(),
      config: getNextAccount(),
      producer: getNextAccount(),
      escrowUsdc: getNextAccount(),
      escrowTitle: getNextAccount(),
      mint: getNextAccount(),
      treasury: getNextAccount(),
      producerUsdc: getNextAccount(),
      treasuryUsdc: getNextAccount(),
      usdcMint: getNextAccount(),
      tokenProgram: getNextAccount(),
      associatedTokenProgram: getNextAccount(),
      systemProgram: getNextAccount(),
    },
    data: getClaimTimeoutInstructionDataDecoder().decode(instruction.data),
  };
}
